package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class IOUtils_skip_TriageGen1Test {







    @Test
    public void testSkip_PartialSkipInLoop() throws IOException {
        // Using a custom InputStream to simulate a skip that doesn't skip the whole amount at once
        // This forces the 'while' loop to run multiple times and tests the 'skipped == 0' break condition
        InputStream partialSkipInputStream = new InputStream() {
            private int pos = 0;
            private final byte[] data = {1, 2, 3, 4, 5};

            @Override
            public int read() throws IOException {
                if (pos >= data.length) return -1;
                return data[pos++] & 0xFF;
            }

            @Override
            public long skip(long n) throws IOException {
                if (n <= 0) return 0;
                // Simulate a slow/partial skip: only skip 1 byte at a time regardless of n
                if (pos < data.length) {
                    pos++;
                    return 1;
                }
                return 0;
            }

            @Override
            public int available() throws IOException {
                return data.length - pos;
            }
        };

        long numToSkip = 3;
        long skipped = IOUtils.skip(partialSkipInputStream, numToSkip);

        assertEquals(3L, skipped);
    }




}

